export const DOCS_CSS: string = "/* The documentation page's own stylesheet: the header, \"Get connected\", the token box,\n   the examples and the guides. The reference viewer brings its own stylesheet, loaded\n   before this one; of the viewer, this file only takes away the two parts the page\n   replaces (see the end).\n\n   Light and dark follow the system. The colours below are the page's; the viewer has its\n   own dark look, switched on by the class \"dark-mode\" on the html element, which the page\n   script sets from the same system setting. The dark background here is the viewer's\n   (#1c2022), so the two meet without a seam. */\n\n:root {\n  color-scheme: light dark;\n  --bg: #ffffff;\n  --fg: #1f2933;\n  --muted: #52606d;\n  --line: #d5dbe1;\n  --panel: #f4f6f8;\n  --code-bg: #eef1f4;\n  --link: #175cab;\n  --button-bg: #175cab;\n  --button-fg: #ffffff;\n  --ok: #1b6b3a;\n  --bad: #a3262c;\n  --focus: #175cab;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n    --bg: #1c2022;\n    --fg: #e4e6e6;\n    --muted: #aab4bc;\n    --line: #3b4348;\n    --panel: #252b2e;\n    --code-bg: #2b3236;\n    --link: #8cc0ff;\n    --button-bg: #8cc0ff;\n    --button-fg: #10202f;\n    --ok: #7fd6a0;\n    --bad: #ffa0a0;\n    --focus: #8cc0ff;\n  }\n}\n\n[hidden] {\n  display: none !important;\n}\n\nhtml {\n  background: var(--bg);\n}\n\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--fg);\n  font-family: system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  font-size: 16px;\n  line-height: 1.5;\n  overflow-wrap: break-word;\n}\n\n/* Every block of our own carries the class \"own\", and every rule below is under it, so\n   nothing here restyles the viewer. They line up with the viewer's column (max-width\n   1460px, 20px at the sides). */\n.own {\n  box-sizing: border-box;\n  margin: 0 auto;\n  max-width: 1460px;\n  padding: 0 20px;\n  width: 100%;\n}\n\n.page-header {\n  padding-top: 32px;\n}\n\n.page-header h1 {\n  font-size: 2rem;\n  line-height: 1.2;\n  margin: 0 0 4px;\n}\n\n.own.page-header p {\n  color: var(--muted);\n  margin: 0 0 4px;\n}\n\n.block {\n  margin-top: 40px;\n}\n\n.own > h2 {\n  border-bottom: 1px solid var(--line);\n  font-size: 1.5rem;\n  line-height: 1.25;\n  margin: 0 0 16px;\n  padding-bottom: 8px;\n}\n\n.own h3 {\n  font-size: 1.1rem;\n  margin: 24px 0 8px;\n}\n\n/* Running text keeps a readable line; commands and tables may use the full width. */\n.own p,\n.own .steps {\n  max-width: 46rem;\n}\n\n.own p {\n  margin: 0 0 12px;\n}\n\n.own a {\n  color: var(--link);\n}\n\n.own a:focus-visible,\n.own button:focus-visible,\n.own input:focus-visible {\n  outline: 2px solid var(--focus);\n  outline-offset: 2px;\n}\n\n.own code,\n.own pre {\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace;\n  font-size: 0.9rem;\n}\n\n.own p code,\n.own td code {\n  background: var(--code-bg);\n  border-radius: 3px;\n  padding: 1px 4px;\n}\n\n.steps {\n  margin: 0 0 16px;\n  padding-left: 1.5rem;\n}\n\n.steps > li {\n  margin-bottom: 12px;\n}\n\n.note,\n.answers,\n.legend {\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n\n/* The token box. */\n.token-box {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  margin: 0 0 16px;\n  max-width: 46rem;\n  padding: 16px;\n}\n\n.token-box label {\n  display: block;\n  font-weight: 600;\n  margin-bottom: 8px;\n}\n\n.token-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.token-row input {\n  background: var(--bg);\n  border: 1px solid var(--muted);\n  border-radius: 4px;\n  box-sizing: border-box;\n  color: var(--fg);\n  flex: 1 1 16rem;\n  font: inherit;\n  min-width: 0;\n  padding: 8px 10px;\n}\n\n.own button {\n  background: var(--button-bg);\n  border: 1px solid var(--button-bg);\n  border-radius: 4px;\n  color: var(--button-fg);\n  cursor: pointer;\n  font: inherit;\n  font-weight: 600;\n  padding: 8px 16px;\n}\n\n.own button.quiet {\n  background: transparent;\n  border-color: var(--muted);\n  color: var(--fg);\n}\n\n.token-box .note {\n  margin: 8px 0 0;\n}\n\n.own .status,\n#reference .status {\n  margin: 8px 0 0;\n  min-height: 1.5em;\n}\n\n.status.ok {\n  color: var(--ok);\n}\n\n.status.bad {\n  color: var(--bad);\n}\n\n/* A command with its copy button. A long command wraps instead of scrolling sideways;\n   copied, it is still one line. */\n.command {\n  align-items: flex-start;\n  background: var(--code-bg);\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  display: flex;\n  gap: 8px;\n  margin: 8px 0;\n  padding: 10px 12px;\n}\n\n.command pre {\n  flex: 1 1 auto;\n  margin: 0;\n  min-width: 0;\n  overflow-wrap: anywhere;\n  white-space: pre-wrap;\n}\n\n.own .command button {\n  flex: 0 0 auto;\n  font-size: 0.85rem;\n  padding: 4px 10px;\n}\n\n.guide-links {\n  margin: 0;\n  padding-left: 1.5rem;\n}\n\n.table-wrap {\n  overflow-x: auto;\n}\n\n.own table {\n  border-collapse: collapse;\n  margin: 0 0 16px;\n  width: 100%;\n}\n\n.own th,\n.own td {\n  border-bottom: 1px solid var(--line);\n  padding: 6px 12px 6px 0;\n  text-align: left;\n  vertical-align: top;\n}\n\n.own th {\n  font-size: 0.9rem;\n}\n\n.limits {\n  margin: 0 0 16px;\n  max-width: 46rem;\n  padding-left: 1.5rem;\n}\n\n#reference {\n  min-height: 4rem;\n}\n\n/* The one line shown in the viewer's place, without JavaScript or when it cannot start. */\n#reference > p {\n  box-sizing: border-box;\n  margin: 0 auto;\n  max-width: 1460px;\n  padding: 0 20px;\n}\n\n.page-footer {\n  border-top: 1px solid var(--line);\n  color: var(--muted);\n  font-size: 0.9rem;\n  margin-top: 48px;\n  padding-bottom: 32px;\n  padding-top: 16px;\n}\n\n@media (max-width: 600px) {\n  .page-header h1 {\n    font-size: 1.6rem;\n  }\n\n  .command {\n    flex-direction: column;\n  }\n\n  .command button {\n    align-self: flex-end;\n  }\n}\n\n/* The viewer's title block and its authorise bar: the page has its own header and token\n   box. With the bar goes the lock button on each request: it opens the viewer's own token\n   dialog, which the viewer draws inside that bar, so with the bar hidden the button would\n   do nothing. Nothing else of the viewer is hidden. The class names are the viewer's own\n   (test/docs-page.test.ts checks its script still uses them). */\n.swagger-ui .information-container,\n.swagger-ui .scheme-container,\n.swagger-ui .authorization__btn {\n  display: none;\n}\n";
